// Image / function tables generated by src/recomp.py (src/gen/table.cpp).
#pragma once
#include <cstdint>
#include "m68k.h"

typedef void (*GuestFn)(Cpu& c, uint32_t pc);

struct FuncEntry {
    uint32_t addr;      // a resumable address (entry, return address, table target, loop head)
    GuestFn fn;
};

struct ImageEntry {
    const char* name;
    int cpu;                    // 0 = main, 1 = sub
    uint32_t base, end;
    uint32_t sig[8];            // first 8 longwords, tells overlays at the same address apart
    const FuncEntry* funcs;     // sorted by addr
    int count;
};

extern const ImageEntry g_images[];
extern const int g_image_count;
